# Verificações de JSF para o nbkit (carregado pelo nbkit.sh com source).
# Instala o módulo nbkit.jsf no NetBeans: avisos no editor de xhtml (EL, ids, formulários, templates...),
# com as mesmas cores dos avisos do Java. Cada regra liga e desliga em Tools > Options > Editor > JSF.

nbkit_registrar jsf jsf ferramenta "Verificações de JSF" "Avisos no editor de xhtml: EL, ids, formulários, templates" 1

jsf_jar() { echo "$UD/modules/nbkit-jsf.jar"; }
jsf_xml() { echo "$UD/config/Modules/nbkit-jsf.xml"; }

jsf_status() {
  if [ -e "$(jsf_jar)" ]; then version_status jsf; else echo nao; fi
}

jsf_caminhos() {
  printf '%s\n' modules/nbkit-jsf.jar config/Modules/nbkit-jsf.xml
}

jsf_passos_instalar() { echo 1; }
jsf_passos_desinstalar() { echo 1; }

jsf_resumo_desinstalar() {
  echo "    ${B}Sai:${N}   o módulo de verificações (os avisos somem do editor de xhtml)"
  echo "    ${B}Fica:${N}  o que você marcou em Tools > Options > Editor > JSF, para uma próxima instalação"
}

jsf_instalar() {
  local jar xml
  jar="$(jsf_jar)"; xml="$(jsf_xml)"
  step "Verificações de JSF (módulo do NetBeans)"
  mkdir -p "$UD/modules" "$UD/config/Modules"
