B64
  echo "13cf43e1d6a04ca24c2e9d0d84759d674f6a537c987e01b84f4f72cbacab9e86  $jar" | sha256sum -c --quiet - || die "o módulo de JSF foi corrompido ao copiar o nbkit."
  cat > "$xml" <<'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE module PUBLIC "-//NetBeans//DTD Module Status 1.0//EN" "http://www.netbeans.org/dtds/module-status-1_0.dtd">
<module name="nbkit.jsf">
    <param name="autoload">false</param>
    <param name="eager">false</param>
    <param name="enabled">true</param>
    <param name="jar">modules/nbkit-jsf.jar</param>
    <param name="reloadable">false</param>
</module>
EOF
  touch "$UD/.lastModified"
  ok "módulo copiado e verificado (sha256)"
  info "as regras ligam e desligam em Tools > Options > Editor > JSF"
}

jsf_desinstalar() {
  step "Removendo as verificações de JSF"
  rm -f "$(jsf_jar)" "$(jsf_xml)"
  touch "$UD/.lastModified"
  ok "módulo removido"
}

jsf_conferir() {
  local errs
  errs="$(log_module_errors 'nbkit\.jsf|nbkit/jsf')"
  if log_has_module 'nbkit\.jsf' && [ -z "$errs" ]; then
    res 0 "módulo de verificações carregado"
    return 0
  fi
  res 1 "módulo de verificações não aparece entre os módulos ligados"
  [ -n "$errs" ] && printf '           %s\n' "$errs"
  if grep -qE 'requires|Java' <<<"$errs"; then return 2; fi
  return 1
}
